content.text:
        raise Reject("syntax")
    if RE_BAD.search(text):
        raise Reject("syntax")
    sep = text.find("\r\n\r\n")
    if sep < 0:
        raise Reject("syntax")
    header = text[:sep]
    body = text[sep + 4:]
    probe = header.replace("\r\n", "")
    if "\r" in probe or "\n" in probe:
        raise Reject("syntax")
    lines = header.split("\r\n")
    # "physical header lines" excludes the request line; logical fields are
    # counted after unfolding below.
    if len(lines) - 1 > MAX_LINES:
        raise Reject("syntax")

    request_line = lines[0]
    parts = request_line.split(" ")
    if len(parts) != 3 or parts[2] != "SIP/2.0":
        raise Reject("syntax")
    method = parts[0]
    if method not in ("INVITE", "MESSAGE"):
        raise Reject("syntax")
    ruri, used = parse_uri(parts[1], 0)
    if used != len(parts[1]) or not ruri.startswith("sip:"):
        raise Reject("syntax")

    fields = []
    for line in lines[1:]:
        if line[:1] == " " or line[:1] == "\t":
            if not fields:
                raise Reject("syntax")
            fields[-1][1] += " " + line.lstrip(WSP)
        else:
            match = RE_NAME.match(line)
            if not match:
                raise Reject("syntax")
            fields.append([match.group(1), line[match.end():]])
    if len(fields) > MAX_FIELDS:
        raise Reject("syntax")

    values = {}
    pai_raw = []
    for name, value in fields:
        key = name.lower()
        key = COMPACT.get(key, key)
        clean = value.strip(WSP)
        if key == "p-asserted-identity":
            pai_raw.append(clean)
        elif key in SINGLETONS:
            if key in values:
                raise Reject("syntax")
            values[key] = clean

    for needed in ("from", "to", "call-id", "cseq", "content-length"):
        if needed not in values:
            raise Reject("syntax")

    match = RE_CSEQ.match(values["cseq"])
    if not match:
        raise Reject("syntax")
    cseq = int(match.group(1))
    if not 1 <= cseq <= MAX_CSEQ:
        raise Reject("syntax")
    if match.group(2) != method:
        raise Reject("syntax")

    callid = values["call-id"]
    if not RE_CALLID.match(callid):
        raise Reject("syntax")

    length = values["content-length"]
    if not length:
        raise Reject("syntax")
    for ch in length:
        if ch not in DEC:
            raise Reject("syntax")
    if int(length) != len(body):
        raise Reject("syntax")

    privacy = None
    if "privacy" in values:
        privacy = values["privacy"].lower()
        if privacy not in ("id", "none"):
            raise Reject("syntax")

    ctype = None
    if "content-type" in values:
        ctype = values["content-type"]
        if not ctype:
            raise Reject("syntax")

    parsed = Parsed()
    parsed.method = method
    parsed.ruri = ruri
    parsed.body = body
    parsed.callid = callid
    parsed.cseq = cseq
    parsed.privacy = privacy
    parsed.ctype = ctype

    parsed.furi, parsed.ftag = parse_address(values["from"], True)
    parsed.fanon = parsed.furi == ANON
    parsed.turi, parsed.ttag = parse_address(values["to"], True)

    parsed.ppi = None
    if "p-preferred-identity" in values:
        parsed.ppi = parse_address(values["p-preferred-identity"], False)[0]
        if parsed.ppi == ANON:
            raise Reject("syntax")
    parsed.rpid = None
    if "remote-party-id" in values:
        parsed.rpid = parse_address(values["remote-party-id"], False)[0]
        if parsed.rpid == ANON:
            raise Reject("syntax")

    pai = []
    for value in pai_raw:
        for member in split_address_list(value):
            uri = parse_address(member, False)[0]
            if uri == ANON:
                raise Reject("syntax")
            pai.append(uri)
    if pai_raw:
        if not 1 <= len(pai) <= 2:
            raise Reject("syntax")
        if len(pai) == 2 and (pai[0].startswith("sip:")
                              == pai[1].startswith("sip:")):
            raise Reject("syntax")
    parsed.pai = pai
    return parsed


